from pathlib import Path

js_path = Path('motion.js')
css_path = Path('motion.css')
js = js_path.read_text()
css = css_path.read_text()

# Career motion should happen on deliberate hover only, not ambient pointer proximity.
old_boot = '    try { careerDepth(); } catch (e) {}\n'
if old_boot in js:
    js = js.replace(old_boot, '    /* Career motion is hover-owned in CSS; no ambient proximity drift. */\n', 1)

marker = '/* ============================================================\n   20. ORIGIN STORY — CURIOSITY TO CLARITY PASS\n   ============================================================ */'
if marker not in css:
    css += '''\n\n/* ============================================================\n   20. ORIGIN STORY — CURIOSITY TO CLARITY PASS\n   ============================================================ */\n\n/* The reading moment starts slightly loose, then resolves cleanly. No layout\n   changes: only the existing Origin elements change timing and motion. */\n.sp-js .story-col.is-origin-ready .origin-curiosity {\n  opacity: 0;\n  transform: translate3d(-10px, 7px, 0) rotate(-0.7deg) scale(.992);\n  transform-origin: left center;\n  filter: blur(.45px);\n  transition: opacity 420ms linear,\n              transform 760ms cubic-bezier(.22,1,.36,1),\n              filter 520ms ease;\n}\n.sp-js .story-col.is-origin-ready .origin-curiosity.is-reached {\n  opacity: 1;\n  transform: none;\n  filter: none;\n}\n\n/* The four thoughts arrive automatically from one scroll trigger. Their tiny\n   alternating offsets make curiosity feel exploratory without changing design. */\n.sp-js .story-col.is-origin-ready .origin-step {\n  opacity: 0;\n  transition: opacity 340ms linear, transform 620ms cubic-bezier(.22,1,.36,1);\n}\n.sp-js .story-col.is-origin-ready .origin-step:nth-of-type(1) {\n  transform: translate3d(-7px, 8px, 0) rotate(-.35deg);\n  transition-delay: 120ms;\n}\n.sp-js .story-col.is-origin-ready .origin-step:nth-of-type(2) {\n  transform: translate3d(6px, 8px, 0) rotate(.24deg);\n  transition-delay: 330ms;\n}\n.sp-js .story-col.is-origin-ready .origin-step:nth-of-type(3) {\n  transform: translate3d(-5px, 8px, 0) rotate(-.2deg);\n  transition-delay: 540ms;\n}\n.sp-js .story-col.is-origin-ready .origin-step:nth-of-type(4) {\n  transform: translate3d(4px, 7px, 0) rotate(.14deg);\n  transition-delay: 760ms;\n}\n.sp-js .story-col.is-origin-ready .origin-step.is-reached {\n  opacity: 1;\n  transform: none;\n}\n\n.sp-js .story-col.is-origin-ready .origin-arrow {\n  opacity: 0;\n  transform: translateY(4px) scale(.94);\n  transition: opacity 260ms linear, transform 440ms cubic-bezier(.22,1,.36,1);\n}\n.sp-js .story-col.is-origin-ready .origin-arrow:nth-of-type(1) { transition-delay: 250ms; }\n.sp-js .story-col.is-origin-ready .origin-arrow:nth-of-type(2) { transition-delay: 460ms; }\n.sp-js .story-col.is-origin-ready .origin-arrow:nth-of-type(3) { transition-delay: 670ms; }\n.sp-js .story-col.is-origin-ready .origin-arrow.is-reached { opacity: 1; transform: none; }\n.sp-js .story-col.is-origin-ready .origin-arrow:nth-of-type(1) path { transition-delay: 250ms; }\n.sp-js .story-col.is-origin-ready .origin-arrow:nth-of-type(2) path { transition-delay: 460ms; }\n.sp-js .story-col.is-origin-ready .origin-arrow:nth-of-type(3) path { transition-delay: 670ms; }\n\n/* After the final thought, hold briefly, then DESIGN FOLLOWED lands as the\n   clarity payoff: straight, sharp and stable. */\n.sp-js .story-col.is-origin-ready .origin-design {\n  opacity: 0;\n  transform: translate3d(0, 10px, 0) scale(.985);\n  filter: blur(.35px);\n  transition: opacity 380ms linear 980ms,\n              transform 700ms cubic-bezier(.22,1,.36,1) 980ms,\n              filter 460ms ease 980ms;\n}\n.sp-js .story-col.is-origin-ready .origin-design.is-reached {\n  opacity: 1;\n  transform: none;\n  filter: none;\n}\n.sp-js .story-col.is-origin-ready .story-body {\n  opacity: 0;\n  transform: translateY(7px);\n  transition: opacity 420ms linear 1160ms,\n              transform 650ms cubic-bezier(.22,1,.36,1) 1160ms;\n}\n.sp-js .story-col.is-origin-ready .story-body.is-reached { opacity: 1; transform: none; }\n\n/* Career is cumulative: every reached company remains fully visible. */\n.sp-js .story-col.is-origin-ready .timeline-item.is-reached,\n.sp-js .story-col.is-origin-ready .timeline-item.is-current {\n  opacity: 1 !important;\n}\n\n/* Each company responds only when deliberately hovered. The row stays anchored;\n   logo, role and date move on separate shallow depth planes. */\n@media (pointer: fine) {\n  .sp-js .story-col .timeline-item.is-reached .tl-logo,\n  .sp-js .story-col .timeline-item.is-reached .tl-body,\n  .sp-js .story-col .timeline-item.is-reached .tl-date {\n    transition: transform 520ms cubic-bezier(.22,1,.36,1);\n    will-change: transform;\n  }\n  .sp-js .story-col .timeline-item.is-reached:hover .tl-logo {\n    transform: translate3d(0, -4px, 0) rotate(.55deg) scale(1.035);\n  }\n  .sp-js .story-col .timeline-item.is-reached:hover .tl-body {\n    transform: translate3d(3px, -2px, 0);\n  }\n  .sp-js .story-col .timeline-item.is-reached:hover .tl-date {\n    transform: translate3d(-2px, 1px, 0);\n  }\n}\n\n@media (prefers-reduced-motion: reduce), (pointer: coarse) {\n  .sp-js .story-col.is-origin-ready .origin-curiosity,\n  .sp-js .story-col.is-origin-ready .origin-step,\n  .sp-js .story-col.is-origin-ready .origin-arrow,\n  .sp-js .story-col.is-origin-ready .origin-design,\n  .sp-js .story-col.is-origin-ready .story-body {\n    opacity: 1 !important;\n    transform: none !important;\n    filter: none !important;\n    transition-delay: 0ms !important;\n  }\n}\n'''

js_path.write_text(js)
css_path.write_text(css)
